package week_01;
import javax.swing.*;import java.awt.*;
public class frm_Menu extends JFrame {
 public frm_Menu(){super("LAB 1 - Mã hóa đối xứng cổ điển");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(600,590);setLocationRelativeTo(null);JPanel p=new JPanel();p.setBorder(BorderFactory.createEmptyBorder(22,40,22,40));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel t=new JLabel("LAB 1 - MÃ HÓA ĐỐI XỨNG CỔ ĐIỂN");t.setFont(new Font("Segoe UI",1,20));p.add(t);p.add(new JLabel("Chọn một bài để mở form tương ứng:"));String[] labels={"1.1 Caesar","1.2 Vigenère","1.3 Rail Fence","1.4 Playfair","1.5 Transposition","1.6 Autokey","Nâng cao 01 - Tổng hợp","Nâng cao 02 - Phân tích","Mở SQLite"};Runnable[] actions={()->new frm_Caesar().setVisible(true),()->new frm_Vigenere().setVisible(true),()->new frm_RailFence().setVisible(true),()->new frm_Playfair().setVisible(true),()->new frm_Transposition().setVisible(true),()->new frm_Autokey().setVisible(true),()->new frm_TongHop().setVisible(true),()->new frm_TanCong().setVisible(true),()->new frm_KetNoiSQL().setVisible(true)};for(int i=0;i<labels.length;i++){final int j=i;JButton b=new JButton(labels[i]);b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setMaximumSize(new Dimension(420,34));b.addActionListener(e->actions[j].run());p.add(Box.createVerticalStrut(8));p.add(b);}p.add(Box.createVerticalStrut(10));p.add(new JLabel("Đóng form con không làm tắt chương trình."));add(p);}
 public static void main(String[]args){SwingUtilities.invokeLater(()->new frm_Menu().setVisible(true));}
}
